export default {
  async fetch(request, env) {
    const path = new URL(request.url).pathname;
    if (path === "/manifest.webmanifest") return new Response(JSON.stringify({name:"The Database",short_name:"Database",description:"Browse and manage a sports card collection.",start_url:"/",display:"standalone",background_color:"#0b0f0d",theme_color:"#0b0f0d"}), {headers:{"content-type":"application/manifest+json"}});
    if (path === "/sw.js") return new Response("const CACHE='the-database-v5';self.addEventListener('install',e=>{self.skipWaiting();e.waitUntil(caches.open(CACHE).then(c=>c.addAll(['/','/collection','/pricing','/scan','/account']))) });self.addEventListener('activate',e=>e.waitUntil(Promise.all([clients.claim(),caches.keys().then(keys=>Promise.all(keys.filter(k=>k!==CACHE).map(k=>caches.delete(k))))])));self.addEventListener('fetch',e=>{if(e.request.method==='GET')e.respondWith(fetch(e.request).catch(()=>caches.match(e.request)))})", {headers:{"content-type":"application/javascript","cache-control":"no-cache"}});
    const routes={"/":"home","/collection":"collection","/pricing":"pricing","/scan":"scan","/account":"account"};
    if (!routes[path]) return new Response("Not found", { status: 404 });
    return new Response(page(routes[path], env), { headers: { "content-type": "text/html; charset=utf-8", "x-content-type-options": "nosniff" } });
  },
};
